Future<Database> initDb() async {
  return await openDatabase(
    'thawani.db',
    version: 3,
    onCreate: (db, version) async {
      await db.execute('CREATE TABLE transactions (id TEXT PRIMARY KEY, amount INTEGER);');
    },
    onUpgrade: (db, oldVersion, newVersion) async {
      if (oldVersion < 2) {
        await db.execute('ALTER TABLE transactions ADD COLUMN merchant_name TEXT;');
      }
      if (oldVersion < 3) {
        await db.execute('CREATE TABLE beneficiaries (id TEXT PRIMARY KEY, iban TEXT);');
      }
    },
  );
}

